    if (!desiPriced.length) continue;
    const all = [...desiPriced, ...((prev[d] && prev[d].s) || [])].slice(0, 40).sort((a, b) => a - b);
    prev[d] = { s: all, price: all[Math.floor(all.length / 2)], at: now };
